// ============================================================
// FraudSentry — hidden-detail detection (pixelation and cover boxes)
//
// A receipt screenshot is generated by the bank / e-wallet app, so it never
// contains a pixel mosaic or a solid box laid over text. When one is there,
// someone edited the image to hide a detail — often the name or the reference
// number, the one field a seller could check in their own app.
//
// Two pixel signals, both measured on the actual image:
//   • MOSAIC TILES. Pixelation averages text and background, so it leaves
//     small FLAT squares in an in-between shade (light blue between white and
//     blue ink). Real anti-aliased text only has 1–2 px of in-between shades
//     at its edges, never a flat 8×8 patch. A cluster of such tiles = mosaic.
//   • COVER BOXES. A flat, detail-free rectangle the height of a text line,
//     in a redaction colour (black, white, or the text's own ink colour).
//     UI cards and buttons are skipped because they contain text, touch the
//     screen edge, are the page's own background colours, or are tinted.
// Pure function over RGBA pixels, so it is unit-tested without a browser.
// ============================================================

export interface ObscuredRegion {
  kind: 'pixelated' | 'covered';
  x: number; y: number; w: number; h: number;   // in the analysed image's pixels
  /** pixelated: number of in-between-shade tiles found; covered: 0 */
  tiles: number;
}

type RGB = [number, number, number];
const dist = (a: number[], b: number[]) => Math.max(Math.abs(a[0] - b[0]), Math.abs(a[1] - b[1]), Math.abs(a[2] - b[2]));

const K = 8;          // side of the flat-patch test box (px)
const STEP = 2;       // scan step (px)
const FLAT_STD = 5;   // max per-channel std. dev. for a "flat" box (JPEG noise allowance)
const WIN = 64;       // window for the local background/ink colours
const MIN_TILES = 3;  // tiles needed before a cluster counts as a mosaic
const MIN_SHADES = 2; // distinct in-between shades needed in that cluster
const SHADE_GAP = 14; // colour distance that makes two tile shades "different"
const RUN_TOL = 10;   // colour tolerance while measuring a tile's flat extent
// Tuned 2026-10-15 on a SYNTHETIC set (34 clean screenshots incl. busy app UI,
// 270 edited copies). Chosen for zero false alarms on that set; looser values
// caught more large-tile mosaics but flagged a clean UI screenshot.
const SHARP = 18;     // colour step that ends a tile
const MIN_OFF = 20;   // a tile shade must be this far from both bg and ink
const T_MIN = 0.08;   // ...and sit between 8 % and 92 % of the way from bg to ink
// A redaction is laid over text on the app's flat UI, so the strip around it
// is a few colours (card background + ink). Photos (in-app ad banners) and
// status-bar icons are many colours. Measured 2026-10-22 on a genuine GCash
// Express Send screenshot with a photo ad, at 828/1179/1290 px wide: false
// hits had ≤ 0.49 of the ring in its 3 commonest colours, real mosaics over
// the name/reference of the same screenshot (6–14 px tiles, JPEG q85) ≥ 0.75.
const RING = 16;      // width of the strip around a region (px)
const RING_TOP3 = 0.6;

/** Mean colour and max channel std. dev. of a w×h box, computed directly
 *  (boxes are tiny, so no whole-image sum tables — those cost ~100 MB on a
 *  phone for a 1080×2400 screenshot). */
function boxStat(data: ArrayLike<number>, W: number, x: number, y: number, w: number, h: number): { m: RGB; sd: number } {
  const s = [0, 0, 0], q = [0, 0, 0]; const n = w * h;
  for (let yy = y; yy < y + h; yy++) for (let xx = x; xx < x + w; xx++) {
    const i = (yy * W + xx) * 4;
    for (let ch = 0; ch < 3; ch++) { const v = data[i + ch]; s[ch] += v; q[ch] += v * v; }
  }
  const m = [s[0] / n, s[1] / n, s[2] / n] as RGB;
  let sd = 0;
  for (let ch = 0; ch < 3; ch++) sd = Math.max(sd, Math.sqrt(Math.max(0, q[ch] / n - m[ch] * m[ch])));
  return { m, sd };
}

/** Most frequent colours (16 levels per channel) in a region, most common first. */
function topColours(data: ArrayLike<number>, W: number, x0: number, y0: number, x1: number, y1: number, step = 2): { c: RGB; share: number }[] {
  const h = new Map<number, { n: number; r: number; g: number; b: number }>();
  let total = 0;
  for (let y = y0; y < y1; y += step) for (let x = x0; x < x1; x += step) {
    const i = (y * W + x) * 4;
    const k = (data[i] >> 4) << 8 | (data[i + 1] >> 4) << 4 | (data[i + 2] >> 4);
    const e = h.get(k);
    if (e) { e.n++; e.r += data[i]; e.g += data[i + 1]; e.b += data[i + 2]; }
    else h.set(k, { n: 1, r: data[i], g: data[i + 1], b: data[i + 2] });
    total++;
  }
  return [...h.values()].sort((a, b) => b.n - a.n).map(e => ({ c: [e.r / e.n, e.g / e.n, e.b / e.n] as RGB, share: e.n / total }));
}

/** Share of the strip around a rectangle taken by its 3 commonest colours. */
function ringTop3(data: ArrayLike<number>, W: number, H: number, x: number, y: number, w: number, h: number): number {
  const x0 = Math.max(0, x - RING), y0 = Math.max(0, y - RING), x1 = Math.min(W, x + w + RING), y1 = Math.min(H, y + h + RING);
  const hist = new Map<number, number>(); let total = 0;
  for (let yy = y0; yy < y1; yy += 2) for (let xx = x0; xx < x1; xx += 2) {
    if (xx >= x && xx < x + w && yy >= y && yy < y + h) continue;
    const i = (yy * W + xx) * 4;
    const k = (data[i] >> 4) << 8 | (data[i + 1] >> 4) << 4 | (data[i + 2] >> 4);
    hist.set(k, (hist.get(k) ?? 0) + 1); total++;
  }
  if (!total) return 1;
  const top = [...hist.values()].sort((a, b) => b - a);
  return ((top[0] ?? 0) + (top[1] ?? 0) + (top[2] ?? 0)) / total;
}

/** Group 8-px grid cells into rectangles (cells within `reach` cells join). */
function clusters(cells: Set<number>, gw: number, reach: number): { x0: number; y0: number; x1: number; y1: number; members: number[] }[] {
  const seen = new Set<number>(); const out = [];
  for (const start of cells) {
    if (seen.has(start)) continue;
    const q = [start]; seen.add(start);
    let x0 = Infinity, y0 = Infinity, x1 = -1, y1 = -1; const members: number[] = [];
    while (q.length) {
      const j = q.pop()!; members.push(j);
      const x = j % gw, y = Math.floor(j / gw);
      x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y);
      for (let dy = -reach; dy <= reach; dy++) for (let dx = -reach; dx <= reach; dx++) {
        const xx = x + dx, yy = y + dy; if (xx < 0 || yy < 0 || xx >= gw) continue;
        const k = yy * gw + xx; if (cells.has(k) && !seen.has(k)) { seen.add(k); q.push(k); }
      }
    }
    out.push({ x0, y0, x1, y1, members });
  }
  return out;
}

export function findObscuredRegions(data: ArrayLike<number>, W: number, H: number): ObscuredRegion[] {
  if (W < 4 * K || H < 4 * K) return [];
  const C = 8, gw = Math.ceil(W / C);

  // ---- mosaic tiles ----
  // A tile is a FLAT, roughly square patch (5–40 px a side) with sharp edges,
  // in an in-between shade of the local background and ink. Its size is
  // measured directly (flat run left/right/up/down from a sample point), so
  // long UI pills, cards and highlighted rows are rejected by their shape.
  const local = new Map<number, { bg: RGB; ink: RGB | null }>();
  const colours = (x: number, y: number) => {
    const wx = Math.floor(x / WIN), wy = Math.floor(y / WIN), key = wy * 100000 + wx;
    let r = local.get(key);
    if (!r) {
      const x0 = Math.max(0, wx * WIN - WIN / 2), y0 = Math.max(0, wy * WIN - WIN / 2);
      const top = topColours(data, W, x0, y0, Math.min(W, x0 + 2 * WIN), Math.min(H, y0 + 2 * WIN));
      const bg = top[0].c;
      const ink = top.find(t => dist(t.c, bg) > 90)?.c ?? null;
      r = { bg, ink }; local.set(key, r);
    }
    return r;
  };
  const px = (x: number, y: number): RGB => { const i = (y * W + x) * 4; return [data[i], data[i + 1], data[i + 2]]; };
  // flat run from (x,y) in direction (dx,dy); returns length and whether it ends in a sharp step
  const run = (x: number, y: number, dx: number, dy: number, c: RGB) => {
    let n = 0, xx = x + dx, yy = y + dy;
    while (xx >= 0 && yy >= 0 && xx < W && yy < H && n < 64 && dist(px(xx, yy), c) <= RUN_TOL) { n++; xx += dx; yy += dy; }
    let sharp = false;
    if (xx >= 0 && yy >= 0 && xx < W && yy < H) {
      const x2 = xx + dx, y2 = yy + dy;
      const beyond = x2 >= 0 && y2 >= 0 && x2 < W && y2 < H ? px(x2, y2) : px(xx, yy);
      sharp = dist(beyond, c) >= SHARP;         // reaches a clearly different colour within 2 px
    }
    return { n, sharp };
  };
  const patches = new Map<string, { x: number; y: number; w: number; h: number; m: RGB }>();
  for (let y = 2; y < H - 2; y += STEP) for (let x = 2; x < W - 2; x += STEP) {
    const { m, sd } = boxStat(data, W, Math.min(x, W - 4) - 1, Math.min(y, H - 4) - 1, 4, 4);
    if (sd > FLAT_STD) continue;
    const { bg, ink } = colours(x, y);
    if (!ink || dist(m, bg) < MIN_OFF || dist(m, ink) < MIN_OFF) continue;
    // an in-between shade: on the bg→ink line, clearly away from both ends
    let num = 0, den = 0;
    for (let ch = 0; ch < 3; ch++) { const d = ink[ch] - bg[ch]; num += (m[ch] - bg[ch]) * d; den += d * d; }
    const t = num / den;
    if (t < T_MIN || t > 1 - T_MIN) continue;
    if (dist(m, bg.map((v, ch) => v + t * (ink[ch] - v))) > 25) continue;
    const L = run(x, y, -1, 0, m), R = run(x, y, 1, 0, m), U = run(x, y, 0, -1, m), D = run(x, y, 0, 1, m);
    const w = L.n + R.n + 1, h = U.n + D.n + 1;
    if (w < 5 || h < 5 || w > 40 || h > 40 || Math.max(w, h) > 2.2 * Math.min(w, h)) continue;
    if ([L, R, U, D].filter(r => r.sharp).length < 3) continue;   // a tile has hard edges
    const px0 = x - L.n, py0 = y - U.n;
    patches.set(`${px0 >> 1},${py0 >> 1}`, { x: px0, y: py0, w, h, m });
  }
  const tileCells = new Map<number, RGB[]>();
  for (const p of patches.values()) {
    const k = Math.floor((p.y + p.h / 2) / C) * gw + Math.floor((p.x + p.w / 2) / C);
    if (!tileCells.has(k)) tileCells.set(k, []);
    tileCells.get(k)!.push(p.m);
  }
  const regions: ObscuredRegion[] = [];
  for (const c of clusters(new Set(tileCells.keys()), gw, 4)) {
    const shades: RGB[] = [];
    let tiles = 0;
    for (const j of c.members) for (const m of tileCells.get(j)!) {
      tiles++;
      if (!shades.some(s2 => dist(s2, m) < SHADE_GAP)) shades.push(m);
    }
    // a mosaic mixes several different averaged shades; one flat UI tint doesn't
    if (tiles < MIN_TILES || shades.length < MIN_SHADES) continue;
    regions.push({ kind: 'pixelated', x: c.x0 * C, y: c.y0 * C, w: (c.x1 - c.x0 + 1) * C, h: (c.y1 - c.y0 + 1) * C, tiles });
  }

  // ---- cover boxes ----
  // page colours (backgrounds) are never a cover box
  const page = topColours(data, W, 0, 0, W, H, 4).filter(t => t.share > 0.08).map(t => t.c);
  const flatCells = new Map<number, RGB>();
  for (let gy = 0; gy * C + C <= H; gy++) for (let gx = 0; gx * C + C <= W; gx++) {
    const { m, sd } = boxStat(data, W, gx * C, gy * C, C, C);
    if (sd <= FLAT_STD && !page.some(p => dist(p, m) < 24)) flatCells.set(gy * gw + gx, m);
  }
  // group same-coloured flat cells
  const byColour = new Map<string, Set<number>>();
  for (const [k, m] of flatCells) {
    const key = m.map(v => Math.round(v / 24)).join(',');
    if (!byColour.has(key)) byColour.set(key, new Set());
    byColour.get(key)!.add(k);
  }
  for (const cells of byColour.values()) {
    for (const c of clusters(cells, gw, 1)) {
      const w = (c.x1 - c.x0 + 1) * C, h = (c.y1 - c.y0 + 1) * C;
      const fill = c.members.length / ((c.x1 - c.x0 + 1) * (c.y1 - c.y0 + 1));
      const touchesEdge = c.x0 === 0 || c.y0 === 0 || (c.x1 + 1) * C >= W - C || (c.y1 + 1) * C >= H - C;
      // a text-line-sized bar: 20–120 px tall, ≥2.5× as wide as tall, solid, inside the image
      if (h < 20 || h > 120 || w < 2.5 * h || w > 0.8 * W || fill < 0.95 || touchesEdge) continue;
      // redaction colours: black, white, or the text's own ink colour. Tinted
      // UI bars (chips, skeleton lines, progress bars) are none of these.
      const m = flatCells.get(c.members[0])!;
      const { bg } = colours((c.x0 + c.x1 + 1) * C / 2, (c.y0 + c.y1 + 1) * C / 2);
      const black = Math.max(...m) < 50;
      const white = Math.min(...m) > 235 && dist(bg, m) > 30;
      // "ink-coloured" only when text in that same colour sits beside it on the
      // line ("Ref No. ████"): the strips left/right are part ink, part background
      const x0 = c.x0 * C, x1 = (c.x1 + 1) * C, y0 = c.y0 * C, y1 = (c.y1 + 1) * C;
      let same = 0, total = 0;
      for (const [a, b] of [[Math.max(0, x0 - 3 * h), x0 - 3], [x1 + 3, Math.min(W, x1 + 3 * h)]]) {
        for (let yy = y0; yy < y1; yy += 2) for (let xx = a; xx < b; xx += 2) { total++; if (dist(px(xx, yy), m) < 40) same++; }
      }
      const inkColoured = total > 0 && same / total > 0.04 && same / total < 0.6;
      if (!black && !white && !inkColoured) continue;
      regions.push({ kind: 'covered', x: c.x0 * C, y: c.y0 * C, w, h, tiles: 0 });
    }
  }
  // drop hits inside photos and icons: a redaction sits on flat UI
  return regions.filter(r => ringTop3(data, W, H, r.x, r.y, r.w, r.h) >= RING_TOP3);
}
